S.setdefault("dark", True)

@st.cache_resource
def get_db():
    conn = sqlite3.connect("pencilpals2.db", check_same_thread=False)
    conn.execute("PRAGMA foreign_keys=ON")
    conn.executescript("""
        CREATE TABLE IF NOT EXISTS users (
            n TEXT PRIMARY KEY, s TEXT, h TEXT,
            role TEXT DEFAULT 'student', grade TEXT DEFAULT '6th Grade',
            bio TEXT DEFAULT '', location TEXT DEFAULT '',
            meeting_mode TEXT DEFAULT 'Virtual', status TEXT DEFAULT 'Available',
            display_name TEXT DEFAULT '', availability TEXT DEFAULT 'Mon-Fri, 3:00-6:00 PM',
            tutor_topics TEXT DEFAULT ''
        );
        CREATE TABLE IF NOT EXISTS att(u TEXT,sub TEXT,unit TEXT,topic TEXT,ok INT,d INT,t REAL,q TEXT);
        CREATE TABLE IF NOT EXISTS msg(u TEXT,tutor TEXT,me INT,txt TEXT,t REAL);
        CREATE TABLE IF NOT EXISTS ses2(u TEXT,tutor TEXT,w TEXT,topic TEXT,link TEXT,sumry TEXT,
            location TEXT DEFAULT '', mode TEXT DEFAULT 'Virtual', status TEXT DEFAULT 'Accepted',
            request_details TEXT DEFAULT '', request_id INTEGER);
        CREATE TABLE IF NOT EXISTS prefs(u TEXT PRIMARY KEY,dark INT);
        CREATE TABLE IF NOT EXISTS tutor_students(
            tutor TEXT, student TEXT, grade TEXT, notes TEXT, status TEXT DEFAULT 'Active',
            UNIQUE(tutor,student));
        CREATE TABLE IF NOT EXISTS tutor_requests(
            id INTEGER PRIMARY KEY AUTOINCREMENT, tutor TEXT, student TEXT,
            request_type TEXT, subject TEXT, details TEXT, date TEXT,
            status TEXT DEFAULT 'Pending', created REAL DEFAULT 0);
        CREATE TABLE IF NOT EXISTS events(
            id INTEGER PRIMARY KEY AUTOINCREMENT, title TEXT, event_type TEXT,
            date TEXT, location TEXT, notes TEXT, host TEXT, created REAL DEFAULT 0);
        CREATE TABLE IF NOT EXISTS deleted_accounts(username TEXT PRIMARY KEY, deleted_at REAL DEFAULT 0);
    """)

    user_columns = {r[1] for r in conn.execute("PRAGMA table_info(users)").fetchall()}
    if "n" not in user_columns:
        conn.execute("ALTER TABLE users RENAME TO users_import_tmp")
        conn.execute("""CREATE TABLE users (
            n TEXT PRIMARY KEY, s TEXT, h TEXT,
            role TEXT DEFAULT 'student', grade TEXT DEFAULT '6th Grade',
            bio TEXT DEFAULT '', location TEXT DEFAULT '', meeting_mode TEXT DEFAULT 'Virtual',
            status TEXT DEFAULT 'Available', display_name TEXT DEFAULT '',
            availability TEXT DEFAULT 'Mon-Fri, 3:00-6:00 PM', tutor_topics TEXT DEFAULT '')""")
        old = {r[1] for r in conn.execute("PRAGMA table_info(users_import_tmp)").fetchall()}
        if {"username", "salt", "hash"}.issubset(old):
            def old_col(col, fallback):
                return col if col in old else fallback
            select_cols = [
                "username", "salt", "hash", old_col("role", "'student'"),
                old_col("grade", "'6th Grade'"), old_col("bio", "''"),
                old_col("location", "''"), old_col("meeting_mode", "'Virtual'"),
                old_col("status", "'Available'"), old_col("display_name", "username"),
                old_col("availability", "'Mon-Fri, 3:00-6:00 PM'"), old_col("tutor_topics", "''")]
            query = "SELECT " + ",".join(select_cols) + " FROM users_import_tmp"
            for row in conn.execute(query).fetchall():
                conn.execute("INSERT OR IGNORE INTO users VALUES(?,?,?,?,?,?,?,?,?,?,?,?)", row)
        conn.execute("DROP TABLE users_import_tmp")
        conn.commit()

    def add_missing(table, cols):
        existing = {r[1] for r in conn.execute(f"PRAGMA table_info({table})").fetchall()}
        for name, decl in cols.items():
            if name not in existing:
                conn.execute(f"ALTER TABLE {table} ADD COLUMN {name} {decl}")
    add_missing("users", {
        "role": "TEXT DEFAULT 'student'", "grade": "TEXT DEFAULT '6th Grade'",
        "bio": "TEXT DEFAULT ''", "location": "TEXT DEFAULT ''",
        "meeting_mode": "TEXT DEFAULT 'Virtual'", "status": "TEXT DEFAULT 'Available'",
        "display_name": "TEXT DEFAULT ''", "availability": "TEXT DEFAULT 'Mon-Fri, 3:00-6:00 PM'",
        "tutor_topics": "TEXT DEFAULT ''"})
    add_missing("ses2", {"location": "TEXT DEFAULT ''", "mode": "TEXT DEFAULT 'Virtual'",
                          "status": "TEXT DEFAULT 'Accepted'", "request_details": "TEXT DEFAULT ''",
                          "request_id": "INTEGER"})
    add_missing("tutor_requests", {"created": "REAL DEFAULT 0"})
    add_missing("events", {"created": "REAL DEFAULT 0"})

    conn.execute("UPDATE users SET role='student' WHERE role IS NULL OR role='' OR role='demo'")
    conn.execute("UPDATE users SET grade='6th Grade' WHERE grade IS NULL OR grade=''")
    conn.execute("UPDATE users SET display_name=n WHERE display_name IS NULL OR display_name=''")
    conn.execute("UPDATE users SET display_name='Alex Morgan' WHERE n='tutor' AND display_name IN ('Jordan Ellis','tutor')")
    conn.execute("DELETE FROM tutor_students WHERE rowid NOT IN (SELECT MAX(rowid) FROM tutor_students GROUP BY tutor, student)")

    conn.execute("DELETE FROM tutor_requests WHERE student='student' AND lower(trim(tutor)) IN ('tutor','alex morgan')")
    conn.execute("DELETE FROM ses2 WHERE u='student' AND lower(trim(tutor)) IN ('tutor','alex morgan')")
    conn.execute("DELETE FROM msg WHERE u='student' AND lower(trim(tutor)) IN ('tutor','alex morgan')")
    conn.execute("DELETE FROM tutor_students WHERE student='student' AND lower(trim(tutor)) IN ('tutor','alex morgan')")
    conn.execute("DELETE FROM tutor_students WHERE tutor IN ('tutor','Alex Morgan') AND student='student'")

    legacy = conn.execute("SELECT n, display_name FROM users WHERE lower(n)='issaamtutor'").fetchone()
    conn.execute("INSERT OR IGNORE INTO deleted_accounts(username, deleted_at) VALUES('issaamtutor', ?)", (time.time(),))
    if legacy:
        legacy_username, legacy_display = legacy
        for table, statement, params in [
            ("att", "DELETE FROM att WHERE u=?", (legacy_username,)),
            ("msg", "DELETE FROM msg WHERE u=? OR tutor=? OR tutor=?", (legacy_username, legacy_display or legacy_username, legacy_username)),
            ("ses2", "DELETE FROM ses2 WHERE u=? OR tutor=? OR tutor=?", (legacy_username, legacy_display or legacy_username, legacy_username)),
            ("tutor_students", "DELETE FROM tutor_students WHERE student=? OR tutor=? OR tutor=?", (legacy_username, legacy_display or legacy_username, legacy_username)),
            ("tutor_requests", "DELETE FROM tutor_requests WHERE student=? OR tutor=? OR tutor=?", (legacy_username, legacy_display or legacy_username, legacy_username)),
            ("prefs", "DELETE FROM prefs WHERE u=?", (legacy_username,)),
            ("events", "DELETE FROM events WHERE host=? OR host=?", (legacy_display or legacy_username, legacy_username)),
        ]:
            conn.execute(statement, params)
        conn.execute("DELETE FROM users WHERE n=?", (legacy_username,))

    conn.execute("DELETE FROM events WHERE title IN (?,?,?,?,?,?,?)", (
        "Regional Math Challenge", "STEM Lab Showcase", "Science Expo",
        "Junior Robotics Tournament", "Writing & Debate Workshop",
        "Earth Science Discovery Day", "Junior Science Fair Finals"))
    conn.commit()
    return conn

db = get_db()
def Q(sql, args=()): return db.execute(sql, args).fetchall()
def X(sql, args=()): db.execute(sql, args); db.commit()
def H(password, salt): return hashlib.pbkdf2_hmac("sha256", password.encode(), salt.encode(), 100000).hex()
def _load_dark(username):
    row = Q("SELECT dark FROM prefs WHERE u=?", (username,))
    return bool(row[0][0]) if row else True
def _set_dark():
    S.dark = bool(S.dark_tgl)
    X("INSERT OR REPLACE INTO prefs VALUES(?,?)", (S.u, int(S.dark)))

