def gen(t, d):
    r, c = random.randint, random.choice
    a, b, k = r(2, 3 + 2 * d), r(2, 4 + 2 * d), r(2, 9)
    w, h = r(2, 4 + 3 * d), r(2, 4 + 3 * d)
    if t == "Addition":
        x, y = r(0, 10 + 10*d), r(0, 10 + 10*d)
        return f"What is {x} + {y}?", x + y
    if t == "Subtraction":
        x = r(0, 10 + 10*d); y = r(0, x)
        return f"What is {x} − {y}?", x - y
    if t == "Counting & Number Patterns":
        start, step = r(0, 15), r(1, max(2, d+2))
        return f"What comes next? {start}, {start+step}, {start+2*step}, {start+3*step}, ?", start+4*step
    if t == "Time & Money":
        price, count = r(1, 5 + d), r(2, 3 + d)
        return f"Pencils cost ${price} each. How much do {count} pencils cost?", price*count
    if t == "Basic Shapes & Symmetry":
        shape, sides = c([("triangle", 3), ("square", 4), ("pentagon", 5), ("hexagon", 6)])
        return f"How many sides does a {shape} have?", sides
    if t == "Linear Equations":
        x, m, b0 = r(1, 12), r(2, 8), r(0, 12)
        return f"Solve for x: {m}x + {b0} = {m*x+b0}.", x
    if t == "Systems of Equations":
        x, y = r(1, 8), r(1, 8)
        return f"Solve the system: x + y = {x+y}; x − y = {x-y}. What is x?", x
    if t == "Quadratic Equations":
        x, y = sorted(random.sample(range(1, 10), 2))
        return f"Solve x² − {x+y}x + {x*y} = 0. What is the smaller solution?", x
    if t == "Functions & Graphs":
        m, b0, x = r(1, 5), r(-6, 8), r(0, 8)
        return f"For f(x) = {m}x + ({b0}), what is f({x})?", m*x+b0
    if t == "Probability":
        red, blue = r(1, 6), r(1, 6)
        return f"A bag has {red} red and {blue} blue marbles. What is the probability of drawing a red marble, as a percentage rounded to the nearest whole number?", round(100*red/(red+blue))
    if t == "Statistics & Data Analysis":
        vals = [r(1, 20) for _ in range(5)]
        return f"What is the mean of {', '.join(map(str, vals))}?", round(sum(vals)/len(vals), 2)
    if t == "Multiplication": return f"What is {a} × {b}?", a * b
    if t == "Division": return f"What is {a * b} ÷ {b}?", a
    if t == "Fractions":
        den = c([2, 3, 4, 5, 10][:min(5, d + 1)]); n = r(1, den - 1); m = r(2, 3 + d) * den
        return f"What is {n}/{den} of {m}?", n * m // den
    if t == "Rounding":
        n, p = r(11, 99 + 90 * d), (10 if d < 3 else c([10, 100]))
        return f"Round {n} to the nearest {p}.", int(n / p + 0.5) * p
    if t == "Place Value":
        n = r(100, 999 * d)
        return (f"In {n}, which digit is in the tens place?", n // 10 % 10) if d < 3 else (f"In {n}, which digit is in the hundreds place?", n // 100 % 10)
    if t == "Area": return (f"A rectangle is {w} by {h}. What is its area?", w * h) if d < 4 else (f"A triangle has base {2*w} and height {h}. What is its area?", w * h)
    if t == "Perimeter": return f"A rectangle is {w} by {h}. What is its perimeter?", 2 * (w + h)
    if t == "Angles":
        x, y = r(20, 20 + 15 * d), r(20, 60)
        return f"Two angles of a triangle are {x}° and {y}°. What is the third angle?", 180 - x - y
    if t == "Volume":
        l, w2, h2 = r(2, 3 + d), r(2, 5), r(2, 5)
        return f"A box is {l} by {w2} by {h2}. What is its volume?", l * w2 * h2
    if t == "Circles":
        n = r(2, 5 + 3 * d)
        if d < 3: return f"A circle has radius {n}. What is its diameter?", 2*n
        if d < 5: return f"A circle has diameter {2*n}. What is its radius?", n
        return f"Using π ≈ 3, what is the circumference of a circle with radius {n}?", 6*n
    if t == "Order of Operations": return (f"{a} + {b} × {k} = ?", a + b*k) if d < 4 else (f"({a} + {b}) × {k} − {a} = ?", (a+b)*k-a)
    if t == "Equations":
        if d <= 2: return f"x + {a} = {a+b}. What is x?", b
        if d == 3: return f"{a}x = {a*b}. What is x?", b
        return f"{a}x + {b} = {a*k+b}. What is x?", k
    if t == "Exponents":
        p = r(2, 4)
        return (f"What is {k}²?", k*k) if d < 4 else (f"What is {p}³?", p**3)
    if t == "Negative Numbers":
        n1, n2 = r(2, 5 + 3*d), r(2, 5 + 3*d)
        return (f"{n1} − {n2} = ?", n1-n2) if d < 3 else (f"−{n1} + {n2} = ?", n2-n1)
    if t == "Patterns":
        s0, step = r(1, 9), r(2, 3+d)
        return (f"What comes next? {s0}, {s0+step}, {s0+2*step}, {s0+3*step}, ?", s0+4*step) if d < 4 else (f"What comes next? {s0}, {2*s0}, {4*s0}, {8*s0}, ?", 16*s0)
    if t == "Percents":
        p = c([10, 20, 25, 50][:min(4, d+1)]); n = c([20, 40, 60, 80, 100, 200])
        return f"What is {p}% of {n}?", p*n//100
    if t == "Ratios": return f"The ratio of cats to dogs is {a}:{b}. If there are {a*k} cats, how many dogs are there?", b*k
    if t == "Median":
        v = random.sample(range(1, 10*d+12), 5)
        return f"What is the median of {', '.join(map(str, v))}?", sorted(v)[2]
    if t == "Unit Rates":
        k2, n = r(2, 4+d), r(2, 6)
        return (f"{n} notebooks cost ${k2*n}. How much does 1 notebook cost?", k2) if d < 3 else (f"A car travels {k2*n*10} miles in {n} hours. How many miles per hour?", k2*10)
    m = r(5, 10*d); x = r(1, 4); vals = [m-x, m, m+x, m]; random.shuffle(vals)
    return f"What is the average of {', '.join(map(str, vals))}?", m

def concept_question(topic):
    correct = LESS.get(topic, f"{topic} is a topic to study and practice.")
    candidates = [v for k, v in LESS.items() if k != topic]
    wrong = random.sample(candidates, 3)
    opts = [correct] + wrong
    random.shuffle(opts)
    return {"q": f"Which statement best describes {topic}?", "o": opts, "a": correct, "d": 2}

def newq(username, topic):
    lv = level(username, topic)
    if topic in BANK and BANK[topic]:
        seen = {r[0] for r in Q("SELECT q FROM att WHERE u=? AND topic=? ORDER BY t DESC LIMIT 9", (username, topic))}
        item = min(BANK[topic], key=lambda x: (x[0] in seen, abs(x[4] - lv), random.random()))
        choices = [item[1], item[2], item[3]]; random.shuffle(choices)
        return {"q": item[0], "o": choices, "a": item[1], "d": item[4]}
    if SUBJ.get(topic) == "Math":
        qtext, ans = gen(topic, lv)
        vals = {ans}; attempts = 0
        while len(vals) < 4:
            attempts += 1
            if topic == "Place Value": x = random.randint(0, 9)
            elif topic == "Rounding": x = ans + random.choice([-100, -10, 10, 100])
            else: x = ans + random.choice([-10, -3, -2, -1, 1, 2, 3, 10])
            if attempts > 40: x = ans + attempts
            if x >= 0 or ans < 0: vals.add(x)
        opts = [str(x) for x in vals]; random.shuffle(opts)
        return {"q": qtext, "o": opts, "a": str(ans), "d": lv}
    return concept_question(topic)

BANK = {}
def B(topic, *questions):
    for item in questions:
        parts = item.split("|")
        if len(parts) == 5:
            q, answer, wrong1, wrong2, difficulty = parts
            BANK.setdefault(topic, []).append((q, answer, wrong1, wrong2, int(difficulty)))

