# Tutor profiles are stored in the users table and initialized by seed_real_tutors().
# This avoids a second, hard-coded showcase roster that can diverge from login accounts.
RAW = []
TUT = []
BASE_TUT_NAMES = []
TUTOR_PLACES = {}

def tutor_profile_row(username=None):
    if username is None:
        username = S.get("u") if S.get("role") == "tutor" else "tutor"
    row = Q("SELECT display_name,bio,location,meeting_mode,status,availability,tutor_topics,grade FROM users WHERE n=?", (username,))
    if row:
        return row[0]
    return ("Alex Morgan", "", "", "Virtual", "Available", "Tue, Thu · 4:00-7:00 PM", "", "12th Grade")

def tutor_catalog():
    out = list(TUT)
    for (n, display_name, grade, bio, location, mode, status, availability, saved_topics) in Q(
        """SELECT n,display_name,grade,bio,location,meeting_mode,status,availability,tutor_topics
           FROM users WHERE role='tutor'
           ORDER BY CASE display_name
               WHEN 'Issaam Mussani' THEN 0
               WHEN 'Kavin Puri' THEN 1
               ELSE 2
           END, display_name COLLATE NOCASE"""):
        if not any(x[0] == display_name for x in out):
            topics = [x for x in saved_topics.split(",") if x in UNIT] or ["Multiplication", "Fractions"]
            days = [x.strip() for x in availability.split("·")[0].split(",") if x.strip()] if "·" in availability else ["Mon", "Wed"]
            hours = availability.split("·",1)[1].strip() if "·" in availability else "3:00-6:00 PM"
            out.append((display_name or n, GRADE_NUMBER.get(str(grade), 12), days, hours,
                        sorted({SUBJ[x] for x in topics}), topics, bio or "Pencil Pals tutor available for personalized student support."))
    return out

def tutor_meta(name):
    if name in TUTOR_PLACES:
        mode, location = TUTOR_PLACES[name]
        return mode, location, "Available"
    saved = Q("SELECT meeting_mode,location,status FROM users WHERE role='tutor' AND display_name=? LIMIT 1", (name,))
    if saved: return saved[0][0] or "Virtual", saved[0][1] or "", saved[0][2] or "Available"
    return ("Virtual", "", "Available")
def window(s):
    try:
        a, b = s.split("-"); marker = b.strip()[-2:]
        def parse(x):
            x = x.strip()
            if x[-2:] not in ("AM", "PM"): x += " " + marker
            return dt.datetime.strptime(x, "%I:%M %p").time()
        return parse(a), parse(b)
    except Exception:
        return dt.time(0,0), dt.time(23,59)

COL = {"Mastered":"#16a34a", "Learning":"#d97706", "Basic":"#dc2626", "Not started":"#64748b"}
def scores(username):
    out = {t: [] for t in UNIT}
    for topic, ok in Q("SELECT topic,ok FROM att WHERE u=? ORDER BY t DESC", (username,)):
        if topic in out and len(out[topic]) < 10: out[topic].append(ok)
    return {t: ("Not started" if not r else "Mastered" if sum(r)>=8 else "Learning" if sum(r)>=5 else "Basic", sum(r), r) for t,r in out.items()}
def ustat(sc, unit):
    topics = [t for t in UNIT if UNIT[t] == unit]
    avg = sum(sc[t][1] for t in topics) / max(1, len(topics))
    return ("Not started" if all(sc[t][0] == "Not started" for t in topics) else "Mastered" if avg >= 8 else "Learning" if avg >= 5 else "Basic"), avg
def weak(sc):
    return sorted([(t, sum(r)/len(r)) for t,(status,n,r) in sc.items() if len(r)>=3 and sum(r)/len(r)<.75], key=lambda x:x[1])
def activity(username):
    out = {}
    for (stamp,) in Q("SELECT t FROM att WHERE u=?", (username,)):
        day = dt.date.fromtimestamp(stamp); out[day] = out.get(day, 0) + 1
    return out
def streak(act):
    day = dt.date.today()
    if day not in act: day -= dt.timedelta(days=1)
    count = 0
    while day in act: count += 1; day -= dt.timedelta(days=1)
    return count
def level(username, topic):
    rows = Q("SELECT ok,d FROM att WHERE u=? AND topic=? ORDER BY t DESC LIMIT 2", (username, topic))
    if not rows:
        g = grade_num(username)
        return max(1, min(5, 1 + max(0, g - 4) // 2))
    d = int(rows[0][1] or 1)
    if not rows[0][0]: return max(1, d-1)
    return min(5, d+1) if len(rows)>1 and rows[1][0] and rows[1][1] == d else d

def recommended_topics(username, sc, limit=4):
    g = grade_num(username)
    low, high = GRADE_BANDS.get(g, (5, 6))
    min_allowed = max(1, low - 1)
    max_allowed = min(12, high + 1)
    if g <= 2:
        max_allowed = 3
    if g >= 5:
        min_allowed = max(4, min_allowed)
    eligible = [t for t in UNIT if min_allowed <= topic_grade(t) <= max_allowed]

    weak_rows = [(t, value) for t, value in weak(sc) if t in eligible]
    weak_rows.sort(key=lambda row: (row[1], random.random()))
    result = [t for t, _ in weak_rows]

    exact_band = [t for t in UNIT if low <= topic_grade(t) <= high and sc[t][0] == "Not started"]
    exact_band.sort(key=lambda t: (abs(topic_grade(t) - g), random.random()))
    adjacent = [t for t in eligible if t not in exact_band and sc[t][0] == "Not started"]
    adjacent.sort(key=lambda t: (abs(topic_grade(t) - g), random.random()))
    attempted = [t for t in eligible if sc[t][0] != "Not started" and t not in result]
    attempted.sort(key=lambda t: (sc[t][1], abs(topic_grade(t) - g), random.random()))

    for pool in (exact_band, adjacent, attempted):
        for topic in pool:
            if topic not in result:
                result.append(topic)
            if len(result) >= limit:
                return result[:limit]
    return result[:limit]

def topic_tutors(topic, catalog=None):
    catalog = catalog or tutor_catalog()
    return [t for t in catalog if topic in t[5]]

def seed_defaults():
    username = "student"
    role = "student"
    display = "Student"
    grade = "6th Grade"
    bio = "A student working toward stronger skills across core subjects."
    if not Q("SELECT 1 FROM deleted_accounts WHERE lower(username)=lower(?)", (username,)):
        existing = Q("SELECT n FROM users WHERE n=?", (username,))
        salt = secrets.token_hex(8)
        if existing:
            X("UPDATE users SET s=?,h=?,role=? WHERE n=?", (salt, H("password", salt), role, username))
        else:
            X("INSERT INTO users(n,s,h,role,grade,bio,location,meeting_mode,status,display_name,availability,tutor_topics) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)",
              (username, salt, H("password", salt), role, grade, bio, "", "Virtual", "Available", display, "", ""))

    if Q("SELECT 1 FROM users WHERE n='student' AND role='student' LIMIT 1") and not Q("SELECT 1 FROM att WHERE u='student' LIMIT 1"):
        plan = {"Multiplication":9,"Division":8,"Fractions":6,"Rounding":10,"Place Value":3,"Area":7,"Perimeter":4,"Angles":5,"Equations":2,"Percents":8,
                "Food Chains":9,"Cells":8,"Water Cycle":5,"Plants & Photosynthesis":7,"Weather & Climate":4,"Colonies":6,"American Revolution":8,
                "Parts of Speech":4,"Sentence Types":9,"Prefixes":6}
        stamp = time.time()-40000
        for topic, correct_n in plan.items():
            answers = [1]*correct_n + [0]*(10-correct_n)
            random.shuffle(answers)
            for ok in answers:
                stamp += 45
                X("INSERT INTO att VALUES(?,?,?,?,?,?,?,?)", ("student", SUBJ[topic], UNIT[topic], topic, ok, random.randint(1,3), stamp, "Sample demo activity"))

    if Q("SELECT 1 FROM users WHERE n='student' AND role='student' LIMIT 1"):
        stu_tutor = "Kavin Puri"
        req = Q("SELECT id,date,details FROM tutor_requests WHERE tutor=? AND student='student' ORDER BY id DESC LIMIT 1", (stu_tutor,))
        if not req:
            req_date = (dt.date.today()+dt.timedelta(days=3)).isoformat()
            cur = db.execute("INSERT INTO tutor_requests(tutor,student,request_type,subject,details,date,status,created) VALUES(?,?,?,?,?,?,?,?)",
                (stu_tutor,"student","Session request","Math","Would like help reviewing fractions before a quiz.",req_date,"Pending",time.time()))
            db.commit()
            req = [(cur.lastrowid, req_date, "Would like help reviewing fractions before a quiz.")]
        rid, req_date, req_details = req[0]
        if not Q("SELECT 1 FROM ses2 WHERE u='student' AND tutor=? LIMIT 1", (stu_tutor,)):
            mode, loc, _ = tutor_meta(stu_tutor)
            X("INSERT INTO ses2(u,tutor,w,topic,link,sumry,location,mode,status,request_details,request_id) VALUES(?,?,?,?,?,?,?,?,?,?,?)",
              ("student", stu_tutor, f"{req_date} 16:00", "Fractions", "", "", loc if mode == "In person" else "", mode, "Pending", req_details, rid))

        if not Q("SELECT 1 FROM ses2 WHERE u='student' AND sumry!='' LIMIT 1"):
            for days_ago, topic, tutor_name, note in [
                (9, "Fractions", "Kavin Puri", "We reviewed finding a fraction of a number and simplifying fractions. You solved several practice problems. Next step: work through the fractions lesson and aim for 8/10. — Kavin"),
                (18, "Equations", "Shreyan Bansal", "We practiced one-step equations and undoing operations on both sides. You are ready to try two-step equations next time. — Shreyan")]:
                past = dt.datetime.combine(dt.date.today()-dt.timedelta(days=days_ago), dt.time(16,0)).strftime("%Y-%m-%d %H:%M")
                X("INSERT INTO ses2(u,tutor,w,topic,link,sumry,location,mode,status,request_details,request_id) VALUES(?,?,?,?,?,?,?,?,?,?,?)",
                  ("student", tutor_name, past, topic, "", note, "", "Virtual", "Completed", "Sample completed session", None))

