def hero(title, sub="", c1="#312e81", c2="#4f46e5", kicker="", small=False):
    st.markdown(f'<div class="hero{" sm" if small else ""}" style="--h1:{c1};--h2:{c2}">'+(f'<div class="kicker">{_h.escape(kicker)}</div>' if kicker else '')+f'<h1>{_h.escape(str(title))}</h1>'+(f'<p>{_h.escape(str(sub))}</p>' if sub else '')+'</div>', unsafe_allow_html=True)
def section(title, subtitle=""):
    st.markdown(f'<div class="sec"><div class="sec-t">{_h.escape(title)}</div>'+(f'<div class="sec-s">{_h.escape(subtitle)}</div>' if subtitle else '')+'</div>', unsafe_allow_html=True)
def box(content, tone="t1"): return f'<div class="box {tone}">{content}</div>'
def pill(status): return f'<span class="pill" style="background:{COL.get(status,"#64748b")}">{_h.escape(status)}</span>'
def bar(frac, color): return f'<div class="bar"><i style="width:{max(0,min(1,frac))*100:.0f}%;background:{color}"></i></div>'
def stat(label,value,note,tone): return f'<div class="stat {tone}"><div class="stat-l">{label}</div><div class="stat-v">{value}</div><div class="stat-n">{note}</div></div>'
def tile(sub): return f'<div class="tile" style="background:{SUBCOL[sub]};color:#fff;font-weight:800;font-size:1.05rem">{SUBICO[sub]}</div>'
def subtx(sub): return SUBLT[sub][0] if S.get("dark",True) else SUBCOL[sub]
def dtile(when_):
    try: d = dt.datetime.strptime(when_, "%Y-%m-%d %H:%M")
    except ValueError: d = dt.datetime.fromisoformat(when_)
    return f'<div class="dtile"><b>{d:%d}</b><span>{d:%b}</span></div>'
def when(when_):
    try: return dt.datetime.strptime(when_, "%Y-%m-%d %H:%M").strftime("%A, %B %d at %I:%M %p").replace(" 0", " ")
    except ValueError: return when_
def foot(): st.markdown('<div class="foot">Pencil Pals · Issaam Mussani & Kavin Puri (2026)</div>', unsafe_allow_html=True)
def go(page, **kwargs):
    for key,value in kwargs.items(): S[key] = value
    st.switch_page(PG[page])

def tcard(t, key, note=""):
    h = 212
    av = f"background:hsl({h:.0f},55%,42%)"
    chips = "".join(f'<span class="chip" style="background:{SUBCOL[SUBJ[x]]}22;color:{subtx(SUBJ[x])}">{_h.escape(x)}</span>' for x in t[5] if x in SUBJ)
    today = '<span class="pill" style="background:#0891b2;margin:0">Available today</span>' if dt.date.today().strftime("%a") in t[2] else ""
    mode, location, status = tutor_meta(t[0])
    meta = f'Grade {t[1]} student · Available {", ".join(t[2])} · {t[3]}'
    where = f'<div class="tmeta">In person · {_h.escape(location)}</div>' if mode == "In person" and location else '<div class="tmeta">Virtual tutoring</div>'
    with st.container(border=True):
        a,b=st.columns([1,6],gap="medium")
        a.markdown(f'<div class="av" style="{av}">{"".join(w[0] for w in t[0].split())}</div>',unsafe_allow_html=True)
        cert_label = "Pencil Pals tutor"
        cert_color = "#0f766e"
        b.markdown(f'<div class="tname tcd">{_h.escape(t[0])}<span class="pill" style="background:{cert_color};margin:0">{cert_label}</span>{today}</div><div class="tmeta">{_h.escape(meta)}</div>{where}<div class="tchips">{chips}</div><div class="tblurb">{_h.escape(t[6])}</div>',unsafe_allow_html=True)
        if note: st.markdown(box(f'<b class="lbl">Why we picked this tutor</b>{_h.escape(note)}',"t2"),unsafe_allow_html=True)
        if status != "Available": st.caption(f"Profile currently marked {status.lower()}.")
        c1,c2=st.columns(2,gap="medium")
        if c1.button("Message",key=f"m_{key}_{t[0]}",use_container_width=True): go("Messages",tutor=t[0])
        if c2.button("Book a session",key=f"b_{key}_{t[0]}",type="primary",use_container_width=True): go("Sessions",tutor=t[0])

def tgrid(items,key,fn):
    with st.container(key="tgrid_"+key):
        for j in range(0,len(items),2):
            if j: st.markdown('<div class="tsp"></div>',unsafe_allow_html=True)
            cols=st.columns(2,gap="large")
            for c_,item in zip(cols,items[j:j+2]):
                with c_: fn(item)

def tree_html(sc, dark, only=None):
    tx, card, bd = ("#eaf0ff","#223056","#4d5e8c") if dark else ("#0f172a","#ffffff","#a9b8d2")
    E = lambda x: _h.escape(str(x), quote=False)
    subs = [sub for sub in CUR if only in (None,sub)]
    topics = [t for sub in subs for ts in CUR[sub].values() for t in ts]; n = len(topics)
    C=760; RS,RU,RT=(175,340,515) if not only else (0,300,500); k=1 if not only else 1.35
    ang={t:2*math.pi*i/n-math.pi/2 for i,t in enumerate(topics)}
    P=lambda a,r:(C+r*math.cos(a),C+r*math.sin(a))
    cmean=lambda group:math.atan2(sum(math.sin(ang[t]) for t in group),sum(math.cos(ang[t]) for t in group))
    edges=[]; nodes=[]
    def edge(a1,r1,a2,r2,col,w):
        m=(r1+r2)/2; (x1,y1),(c1x,c1y),(c2x,c2y),(x2,y2)=P(a1,r1),P(a1,m),P(a2,m),P(a2,r2)
        edges.append(f'<path d="M{x1:.0f} {y1:.0f}C{c1x:.0f} {c1y:.0f} {c2x:.0f} {c2y:.0f} {x2:.0f} {y2:.0f}" stroke="{col}" stroke-width="{w}" fill="none" opacity=".7" stroke-linecap="round"/>')
    for sub in subs:
        units=CUR[sub]; sub_topics=[t for group in units.values() for t in group]; sa=cmean(sub_topics); sx,sy=P(sa,RS)
        if not only: edge(sa-.35,0,sa,RS,SUBCOL[sub],8)
        for unit,ts in units.items():
            ua=cmean(ts); stt,avg=ustat(sc,unit); ux,uy=P(ua,RU)
            edge(sa-.3 if not only else ua,RS,ua,RU,COL[stt],5)
            for topic in ts:
                status,score,results=sc[topic]; a=ang[topic]; x,y=P(a,RT); lx,ly=P(a,RT+28*k); flip=math.cos(a)<0
                edge(ua,RU,a,RT,COL[status],2.8)
                nodes.append(f'<g class="n {"gl" if status=="Mastered" else ""}"><title>{E(topic)}: {score}/10 · {status}</title><circle cx="{x:.0f}" cy="{y:.0f}" r="{19*k:.0f}" fill="{COL[status]}" stroke="{card}" stroke-width="3"/><text x="{x:.0f}" y="{y:.0f}" dy="5" text-anchor="middle" fill="#fff" font-size="{15*k:.0f}" font-weight="700">{score}</text></g>')
                nodes.append(f'<text x="{lx:.0f}" y="{ly:.0f}" dy="5" transform="rotate({math.degrees(a)+(180 if flip else 0):.1f} {lx:.0f} {ly:.0f})" text-anchor="{"end" if flip else "start"}" font-size="{16*k:.0f}" fill="{tx}">{E(topic)}</text>')
            nodes.append(f'<g class="n"><title>{E(unit)}: {stt}</title><circle cx="{ux:.0f}" cy="{uy:.0f}" r="{29*k:.0f}" fill="{card}" stroke="{COL[stt]}" stroke-width="7"/><text x="{ux:.0f}" y="{uy:.0f}" dy="5" text-anchor="middle" fill="{tx}" font-size="{15*k:.0f}" font-weight="700">{avg:.1f}</text></g>')
            nodes.append(f'<text class="h" x="{ux:.0f}" y="{uy+50*k:.0f}" text-anchor="middle" font-size="{15*k:.0f}" font-weight="700" fill="{tx}">{E(unit)}</text>')
        if not only:
            nodes.append(f'<g class="n"><circle cx="{sx:.0f}" cy="{sy:.0f}" r="46" fill="{SUBCOL[sub]}"/><text x="{sx:.0f}" y="{sy:.0f}" dy="9" text-anchor="middle" font-size="28" font-weight="800" fill="#fff">{SUBICO[sub]}</text></g>')
            nodes.append(f'<text class="h" x="{sx:.0f}" y="{sy+72:.0f}" text-anchor="middle" font-size="17" font-weight="800" fill="{tx}">{E(sub)}</text>')
    if only:
        nodes.append(f'<g class="n"><circle cx="{C}" cy="{C}" r="78" fill="{SUBCOL[only]}"/><text x="{C}" y="{C}" dy="-2" text-anchor="middle" font-size="40" font-weight="800" fill="#fff">{SUBICO[only]}</text><text x="{C}" y="{C+36}" text-anchor="middle" fill="#fff" font-size="17" font-weight="800">{E(only)}</text></g>')
    else:
        nodes.append(f'<g class="n"><circle cx="{C}" cy="{C}" r="62" fill="#4f46e5"/><text x="{C}" y="{C}" dy="8" text-anchor="middle" fill="#fff" font-size="26" font-weight="800">You</text></g>')
    counts={s:sum(1 for t in topics if sc[t][0]==s) for s in COL}
    legend="".join(f'<span style="margin-right:26px;white-space:nowrap"><i style="display:inline-block;width:14px;height:14px;border-radius:50%;background:{color};margin-right:8px;vertical-align:-2px"></i>{status} ({counts[status]})</span>' for status,color in COL.items())
    return f'''<style>@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;600;700&display=swap');</style><div class="skillmap-wrap" style="max-width:1120px;margin:0 auto;font:15px Inter,Segoe UI,system-ui,sans-serif;color:{tx};background:{card};border:1.5px solid {bd};border-radius:14px;padding:18px 20px;box-sizing:border-box"><div style="margin-bottom:6px">{legend}</div><svg viewBox="0 0 {2*C} {2*C}" style="width:100%;height:auto;display:block"><style>.n{{transition:transform .12s ease-out;transform-box:fill-box;transform-origin:center;cursor:help}}.n:hover{{transform:scale(1.04)}}.h{{paint-order:stroke;stroke:{card};stroke-width:5px;stroke-linejoin:round}}text{{font-family:Inter,Segoe UI,system-ui,sans-serif}}</style>{''.join(edges)}{''.join(nodes)}</svg></div>'''

def home():
    username=S.u; sc=scores(username); total,correct=Q("SELECT COUNT(*),COALESCE(SUM(ok),0) FROM att WHERE u=?",(username,))[0]
    xp=correct*10; act=activity(username); days=streak(act); today_done=act.get(dt.date.today(),0)>0
    hero(f"Welcome back, {username}", "Pick up where you left off, work on your focus areas, or open a new subject.", "#312e81", "#0891b2", "Your dashboard")
    cols=st.columns(5,gap="medium"); mastered=sum(v[0]=="Mastered" for v in sc.values())
    cols[0].markdown(stat("Experience",f"{xp:,} XP",f"Level {xp//100+1} · {100-xp%100} XP to the next level","t1"),unsafe_allow_html=True)
    cols[1].markdown(stat("Accuracy",f"{100*correct//total if total else 0}%","Across every question you've answered","t2"),unsafe_allow_html=True)
    cols[2].markdown(stat("Questions answered",f"{total:,}","Answer more questions to level up","t3"),unsafe_allow_html=True)
    cols[3].markdown(stat("Topics mastered",f"{mastered} / {len(sc)}","Score 8 of 10 or better to master a topic","t4"),unsafe_allow_html=True)
    cols[4].markdown(stat("Day streak",f"{days} day{'s' if days!=1 else ''}","You practiced today." if today_done else "Answer a question today to keep it going" if days else "Answer a question to start a streak","t5"),unsafe_allow_html=True)
    with st.expander("Personalize recommendations with your grade level"):
        current_grade_row=Q("SELECT grade FROM users WHERE n=?",(username,)); current_grade=current_grade_row[0][0] if current_grade_row else "6th Grade"
        grade_options=[f"{n}{'st' if n==1 else 'nd' if n==2 else 'rd' if n==3 else 'th'} Grade" for n in range(1,13)]
        if current_grade not in grade_options: current_grade="6th Grade"
        grade_choice=st.selectbox("Saved grade level",grade_options,index=grade_options.index(current_grade),key="home_grade")
        if st.button("Save grade and refresh recommendations",key="save_grade_home",type="primary"):
            X("UPDATE users SET grade=? WHERE n=?",(grade_choice,username))
            X("UPDATE tutor_students SET grade=? WHERE student=?",(grade_choice,username))
            st.success("Grade saved. Recommendations and starting difficulty have been refreshed."); st.rerun()
    section("Your learning paths","Open a subject to see its units and topics.")
    grid=st.columns(4,gap="medium")
    for col,(sub,units) in zip(grid,CUR.items()):
        topics=[t for ts in units.values() for t in ts]; ms=sum(sc[t][0]=="Mastered" for t in topics); progress=sum(sc[t][1] for t in topics)/(10*len(topics))
        chips="".join(f'<span class="chip" style="background:{SUBCOL[sub]}22;color:{subtx(sub)}">{_h.escape(un)}</span>' for un in units)
        with col.container(border=True):
            st.markdown(f'<div class="pcard tc-mark s{SUBIDX[sub]}"><div class="row">{tile(sub)}<div class="card-t">{sub}</div></div><div class="card-s" style="margin-top:14px">{SUBDESC[sub]}</div>{bar(progress,SUBCOL[sub])}<div class="meta"><span><b>{ms}</b> of {len(topics)} topics mastered</span><span>{int(progress*100)}%</span></div><div style="margin-top:12px">{chips}</div></div>',unsafe_allow_html=True)
            if st.button(f"Open {sub}",key=f"hs_{sub}",use_container_width=True): go("Learn",subject=sub,topic=None,qt=None)
    L,R=st.columns(2,gap="medium")
    with L:
        section("Continue learning","Pick up right where you left off.")
        last=Q("SELECT topic FROM att WHERE u=? ORDER BY t DESC LIMIT 1",(username,)); nxt=last[0][0] if last and last[0][0] in UNIT else recommended_topics(username,sc,1)[0]
        with st.container(border=True):
            st.markdown(f'<div class="hcard"><div class="row">{tile(SUBJ[nxt])}<div><div class="card-t">{_h.escape(nxt)}</div><div class="card-s">{SUBJ[nxt]} · {UNIT[nxt]}</div></div></div><div style="margin-top:16px">{pill(sc[nxt][0])}<b>{sc[nxt][1]}/10</b> correct in your last 10</div>{bar(sc[nxt][1]/10,COL[sc[nxt][0]])}</div>',unsafe_allow_html=True)
            buttons=st.columns(2,gap="medium")
            if buttons[0].button("Resume practice",type="primary",key="res",use_container_width=True): go("Learn",subject=SUBJ[nxt],topic=nxt,qt=None)
            if buttons[1].button(f"Browse {SUBJ[nxt]}",key="hs_br",use_container_width=True): go("Learn",subject=SUBJ[nxt],topic=None,qt=None)
    with R:
        section("Next session","Your next meeting with a tutor.")
        now=dt.datetime.now().strftime("%Y-%m-%d %H:%M")
        nx=Q("SELECT tutor,w,topic,link,mode,location,status FROM ses2 WHERE u=? AND w>=? AND sumry='' AND status!='Declined' ORDER BY w LIMIT 1",(username,now))
        with st.container(border=True):
            if nx:
                r=nx[0]; loc=f'<br>{_h.escape(r[5])}' if r[4]=="In person" and r[5] else ""
                st.markdown(f'<div class="hcard"><div class="row">{dtile(r[1])}<div><div class="card-t">{_h.escape(r[0])}</div><div class="card-s">{when(r[1])}<br>{_h.escape(r[2])}{loc}<br>Status: {_h.escape(r[6])}</div></div></div></div>',unsafe_allow_html=True)
                k=st.columns(2,gap="medium")
                if r[4]=="Virtual": k[0].link_button("Join meeting",r[3],use_container_width=True)
                else: k[0].write("In-person session")
                if k[1].button("All sessions",key="hs_ses",use_container_width=True): go("Sessions")
            else:
                st.markdown('<div class="hcard">'+box("<b class='lbl'>No sessions booked yet</b>Pick a tutor and choose a time that works for you.","t5")+'</div>',unsafe_allow_html=True)
                k=st.columns(2,gap="medium")
                if k[0].button("Find a tutor",type="primary",key="hs_ft0",use_container_width=True): go("Tutors")
                if k[1].button("Book a session",key="hs_bk0",use_container_width=True): go("Sessions")
    section("Your week","Questions you answered over the last 7 days.")
    days_list=[dt.date.today()-dt.timedelta(days=i) for i in range(6,-1,-1)]; mx=max([act.get(day,0) for day in days_list]+[1]); cells=""
    for day in days_list:
        val=act.get(day,0); label="Today" if day==dt.date.today() else day.strftime("%a")
        cells+=f'<div class="wk"><div class="wk-b"><i class="{"" if val else "z"}" style="height:{max(6,100*val//mx)}%"></i></div><b>{val}</b><span>{label}</span></div>'
    with st.container(border=True): st.markdown(f'<div class="wkgrid">{cells}</div>',unsafe_allow_html=True)
    section("Focus areas","Topics where your recent accuracy is below 75%.")
    weak_rows=weak(sc)
    if not weak_rows: st.markdown(box("<b class='lbl'>Nothing to fix yet</b>Answer a few questions and we'll spot the topics that need extra practice.","t1"),unsafe_allow_html=True)
    else:
        cols=st.columns(4,gap="medium")
        for col,(topic,accuracy) in zip(cols,weak_rows[:4]):
            with col.container(border=True):
                st.markdown(f'<div class="tc-t">{_h.escape(topic)}</div><div class="card-s">{SUBJ[topic]} · {int(accuracy*100)}% recent accuracy</div>{bar(accuracy,COL["Basic"] if accuracy<.5 else COL["Learning"])}',unsafe_allow_html=True)
                if st.button("Practice",key=f"w_{topic}",use_container_width=True): go("Learn",subject=SUBJ[topic],topic=topic,qt=None)
        if st.button("Find a tutor for these topics",key="ft"): go("Tutors")
    foot()

def topic_view(sc):
    topic=S.topic; unit=UNIT[topic]; sub=SUBJ[topic]; status,score,rec=sc[topic]; siblings=CUR[sub][unit]; idx=siblings.index(topic)
    b1,b2,b3=st.columns(3,gap="medium")
    if b1.button(f"Back to {sub}",key="back",use_container_width=True): S.topic=None; S.qt=None; st.rerun()
    if idx>0 and b2.button(f"Previous: {siblings[idx-1]}",key="prevt",use_container_width=True): S.topic=siblings[idx-1]; S.qt=None; st.rerun()
    if idx+1<len(siblings) and b3.button(f"Next topic: {siblings[idx+1]}",key="nextt",type="primary",use_container_width=True): S.topic=siblings[idx+1]; S.qt=None; st.rerun()
    hero(topic,f"{sub} · {unit}",SUBCOL[sub],SUBCOL2[sub],f"Topic {idx+1} of {len(siblings)} in {unit}",small=True)
    dots="".join(f'<span class="dot" style="background:{"#16a34a" if x else "#dc2626"}"></span>' for x in reversed(rec))+'<span class="dot" style="background:var(--trk)"></span>'*(10-len(rec))
    st.markdown(box(f'{pill(status)}<b>{score}/10</b> correct in your last 10 answers &nbsp;&nbsp; {dots}<br><span style="color:var(--mu);font-size:.92rem">Mastered = 8+/10 · Learning = 5-7/10 · Basic = 1-4/10 · Not started = no answers yet</span>',"t0"),unsafe_allow_html=True)
    practice_tab,lesson_tab,tutor_tab=st.tabs(["Practice","Lesson","Tutors for this topic"])
    with lesson_tab:
        st.markdown(box(f'<b class="lbl">Key idea</b><span style="font-size:1.15rem">{_h.escape(LESS[topic])}</span>',"t1"),unsafe_allow_html=True)
        st.markdown(box(f'<b class="lbl">Your goal</b>Answer 8 of your last 10 questions correctly to master {_h.escape(topic)}. Questions get harder as you improve.',"t3"),unsafe_allow_html=True)
    with tutor_tab:
        catalog=tutor_catalog(); matches=topic_tutors(topic,catalog)
        tgrid(matches,"topic",lambda t:tcard(t,"topic"))
        if not matches: st.markdown(box("No tutor lists this topic yet. Browse the Tutors page for others in this subject.","t5"),unsafe_allow_html=True)
    with practice_tab:
        if S.get("qt")!=topic:
            S.q=newq(S.u,topic); S.qt=topic; S.done=None; S.n=S.get("n",0)+1; S.sess=[0,0]
        q=S.q; leveldots="".join(f'<span class="dot" style="background:{SUBCOL[sub] if i<q["d"] else "var(--trk)"};width:12px;height:12px"></span>' for i in range(5))
        st.markdown(f'<div class="qbox"><div class="qmeta">Question {S.sess[1]+1} · This visit: {S.sess[0]} of {S.sess[1]} correct</div><div class="qtext">{_h.escape(q["q"])}</div><div class="qmeta">Difficulty {leveldots} Questions adapt to how you are doing.</div></div>',unsafe_allow_html=True)
        if S.done is None:
            choice=st.radio("Pick an answer",q["o"],index=None,key=f"radio_{S.n}",label_visibility="collapsed")
            if st.button("Submit answer",type="primary",disabled=choice is None):
                correct=choice==q["a"]
                X("INSERT INTO att VALUES(?,?,?,?,?,?,?,?)",(S.u,sub,unit,topic,int(correct),q["d"],time.time(),q["q"]))
                S.done=correct; S.sess=[S.sess[0]+int(correct),S.sess[1]+1]
                S.cele=scores(S.u)[topic][0]=="Mastered" and status!="Mastered"; st.rerun()
        else:
            st.markdown('<div class="fb ok">Correct. +10 XP</div>' if S.done else f'<div class="fb no">Not quite. The correct answer is <b>{_h.escape(str(q["a"]))}</b>.</div>',unsafe_allow_html=True)
            if S.pop("cele",False): st.balloons(); st.success("Topic mastered.")
            if st.button("Next question",type="primary"):
                S.q=newq(S.u,topic); S.done=None; S.n+=1; st.rerun()
    foot()

def learn():
    username=S.u; sc=scores(username)
    if S.get("topic"): return topic_view(sc)
    S.setdefault("subject","Math")
    hero("Learn","Choose a subject, then open any topic to read the lesson and practice.","#3730a3","#6366f1","Curriculum")
    with st.container(key="subtabs"):
        cols=st.columns(len(CUR),gap="medium")
        for col,sub in zip(cols,CUR):
            if col.button(sub,key=f"sub_{sub}",type="primary" if S.subject==sub else "secondary",use_container_width=True): S.subject=sub; st.rerun()
    query=st.text_input("Search",placeholder="Search every subject for a topic or unit (try: geometry, fractions, cells)",label_visibility="collapsed",key="lq").lower().strip()
    shown=False; subjects=list(CUR) if query else [S.subject]
    for sub in subjects:
        units=CUR[sub]; all_topics=[t for group in units.values() for t in group]
        if query and not any(query in t.lower() or query in unit.lower() for unit,group in units.items() for t in group): continue
        progress=sum(sc[t][1] for t in all_topics)/(10*len(all_topics)); mastered=sum(sc[t][0]=="Mastered" for t in all_topics)
        if shown: st.markdown('<div class="udiv"></div>',unsafe_allow_html=True)
        st.markdown(box(f'<div class="row">{tile(sub)}<div style="flex:1"><div class="card-t">{sub}</div><div class="card-s">{SUBDESC[sub]}</div></div><div style="text-align:right;min-width:210px"><b>{mastered}</b> of {len(all_topics)} topics mastered{bar(progress,SUBCOL[sub])}</div></div>',"t0"),unsafe_allow_html=True)
        for unit,topics in units.items():
            hits=[t for t in topics if not query or query in t.lower() or query in unit.lower()]
            if not hits: continue
            st.markdown('<div class="udiv"></div>' if shown else '',unsafe_allow_html=True); shown=True
            unit_status,avg=ustat(sc,unit)
            st.markdown(f'<div class="unit-h"><b>{_h.escape(unit)}</b>{pill(unit_status)}<span class="a">Average {avg:.1f} / 10 · {len(topics)} topics</span></div>',unsafe_allow_html=True)
            with st.container(key="lgrid_"+"".join(ch for ch in unit if ch.isalnum())):
                for j in range(0,len(hits),3):
                    cols=st.columns(3,gap="medium")
                    for col,topic in zip(cols,hits[j:j+3]):
                        with col.container(border=True):
                            stt,n_t,_=sc[topic]
                            st.markdown(f'<div class="tc-t tc-mark s{SUBIDX[sub]}">{_h.escape(topic)}</div><div class="tc-m">{pill(stt)}<b>{n_t}/10</b></div>{bar(n_t/10,COL[stt])}',unsafe_allow_html=True)
                            if st.button("Start" if stt=="Not started" else "Open",key=f"open_{topic}",use_container_width=True,type="primary" if stt=="Not started" else "secondary"):
                                S.topic=topic; S.subject=sub; S.qt=None; st.rerun()
    if query and not shown: st.markdown(box("<b class='lbl'>No topics found</b>Try a different word, like a subject name or a unit.","t3"),unsafe_allow_html=True)
    foot()

