def student_tutoring():
    username=S.u; sc=scores(username); grade=Q("SELECT grade FROM users WHERE n=?",(username,))[0][0]
    hero("Tutoring Center","Find personalized support, track your upcoming sessions, and choose what to work on next.","#6d28d9","#db2777","Your support hub")
    recommended=recommended_topics(username,sc,4); weak_topics_now={t for t,_ in weak(sc)}
    section("Your recommended next steps",f"Recommendations use your saved {grade} grade band and recent practice. Grade-appropriate focus topics come first.")
    cols=st.columns(min(4,len(recommended)),gap="medium")
    for col,topic in zip(cols,recommended):
        status,score,_=sc[topic]
        with col.container(border=True):
            label="Focus area" if topic in weak_topics_now else f"Suggested for {grade}"
            st.markdown(f'<div class="card-t">{_h.escape(topic)}</div><div class="card-s">{_h.escape(label)} · {SUBJ[topic]}</div><div style="margin-top:12px">{pill(status)}<b>{score}/10</b></div>{bar(score/10,COL[status])}',unsafe_allow_html=True)
            if st.button("Practice this",key=f"tutor_reco_{topic}",type="primary",use_container_width=True): go("Learn",subject=SUBJ[topic],topic=topic,qt=None)
    weaklist=weak(sc)
    candidates=[]
    catalog=tutor_catalog()
    needs=set(t for t,_ in weaklist[:5])
    if not needs: needs=set(recommended[:3])
    for tutor in catalog:
        overlap=[t for t in tutor[5] if t in needs]
        if overlap: candidates.append((len(overlap),tutor,overlap))
    candidates.sort(key=lambda x:(-x[0],x[1][0]))
    section("Tutors matched to your needs","Matches use the topics you are working on and each tutor's listed strengths.")
    if candidates:
        tgrid([(score,t,overlap) for score,t,overlap in candidates[:4]],"student_reco",lambda item:tcard(item[1],"stu", "Strong in "+", ".join(item[2])+", which fits your current practice."))
    else: st.markdown(box("<b class='lbl'>Keep exploring</b>Answer a few practice questions to unlock more personalized tutor matches, or browse all tutors.","t5"),unsafe_allow_html=True)
    if st.button("Browse all tutors",key="tutoring_browse",use_container_width=False): go("Tutors")
    section("Upcoming tutoring","Requests and sessions are kept here so you can check the current status.")
    now=dt.datetime.now().strftime("%Y-%m-%d %H:%M")
    rows=Q("SELECT tutor,w,topic,link,location,mode,status,request_details FROM ses2 WHERE u=? AND w>=? AND status!='Declined' ORDER BY w LIMIT 5",(username,now))
    if not rows: st.markdown(box("<b class='lbl'>No upcoming sessions</b>Choose a tutor and request your first meeting. You'll see the status here.","t5"),unsafe_allow_html=True)
    for tutor,when_,topic,link,location,mode,status,details in rows:
        with st.container(border=True):
            c1,c2=st.columns([4,2],gap="large",vertical_alignment="center")
            location_line=f'<div class="card-s">Location: {_h.escape(location)}</div>' if mode=="In person" and location else '<div class="card-s">Virtual session</div>'
            c1.markdown(f'<div class="row">{dtile(when_)}<div><div class="card-t">{_h.escape(tutor)}</div><div class="card-s">{when(when_)} · {_h.escape(topic)}</div>{location_line}<div style="margin-top:8px">{_h.escape(status)}</div></div></div>',unsafe_allow_html=True)
            if details: c1.caption(details)
            if mode=="Virtual" and link: c2.link_button("Open meeting link",link,use_container_width=True)
            elif mode=="In person": c2.info("Meet at the listed location.")
            else: c2.caption("Meeting details will appear after the tutor accepts.")
    section("Recent requests","Requests and scheduling responses from your tutors.")
    reqs=Q("SELECT tutor,request_type,subject,details,date,status FROM tutor_requests WHERE student=? ORDER BY created DESC,id DESC LIMIT 5",(username,))
    if not reqs: st.markdown(box("No requests yet. Book a session to send a request to a tutor.","t0"),unsafe_allow_html=True)
    for tutor,typ,subject,details,date_,status in reqs:
        with st.container(border=True):
            badge_color = "#d97706" if status == "Pending" else "#16a34a" if status in ("Accepted", "Completed") else "#dc2626"
            st.markdown(f'<div class="row"><div style="flex:1"><div class="card-t">{_h.escape(tutor)}</div><div class="card-s">{_h.escape(typ)} · {_h.escape(subject)} · {_h.escape(date_)}</div><div>{_h.escape(details or "No additional notes.")}</div></div><div><span class="pill" style="background:{badge_color}">{_h.escape(status)}</span></div></div>',unsafe_allow_html=True)
    foot()

def tutors():
    catalog=tutor_catalog(); sc=scores(S.u); hero("Find a tutor","Browse student tutor profiles and contact them directly or request a session.","#6d28d9","#db2777","Student tutor profiles")
    recommended_tab,browse_tab=st.tabs(["Recommended for you","Browse all tutors"])
    with recommended_tab:
        weakdict=dict(weak(sc)); recommendations=[]
        for tutor in catalog:
            matched=[x for x in tutor[5] if x in weakdict]
            if matched: recommendations.append((sum(1-weakdict[x] for x in matched),tutor,matched))
        recommendations.sort(key=lambda x:-x[0])
        if not recommendations:
            topics=recommended_topics(S.u,sc,3)
            for tutor in catalog:
                matched=[x for x in tutor[5] if x in topics]
                if matched: recommendations.append((len(matched),tutor,matched))
            recommendations.sort(key=lambda x:-x[0])
        if recommendations:
            tgrid(recommendations[:4],"recommended",lambda item:tcard(item[1],"recommended","Strong in "+", ".join(item[2])+", which matches your current practice."))
        else: st.markdown(box("<b class='lbl'>No recommendations yet</b>Answer a few more practice questions and we'll match you with tutors who are strong where you need help.","t5"),unsafe_allow_html=True)
    with browse_tab:
        with st.container(border=True):
            cols=st.columns([2,1,1,1],gap="medium")
            text=cols[0].text_input("Search name or topic",key="tutor_search").lower().strip()
            subjects=cols[1].multiselect("Subject",list(CUR),key="tutor_subject_filter")
            days=cols[2].multiselect("Day",["Mon","Tue","Wed","Thu","Fri","Sat","Sun"],key="tutor_day_filter")
            mode_filter=cols[3].selectbox("Meeting mode",["Any","Virtual","In person"],key="tutor_mode_filter")
        found=[]
        for tutor in catalog:
            mode,location,status=tutor_meta(tutor[0])
            if text and text not in tutor[0].lower() and not any(text in x.lower() for x in tutor[5]): continue
            if subjects and not set(subjects).intersection(tutor[4]): continue
            if days and not set(days).intersection(tutor[2]): continue
            if mode_filter != "Any" and mode != mode_filter: continue
            found.append(tutor)
        st.caption(f"{len(found)} tutors match")
        tgrid(found,"browse",lambda tutor:tcard(tutor,"browse"))
        if not found: st.markdown(box("<b class='lbl'>No tutors match</b>Remove a filter to see more tutors.","t3"),unsafe_allow_html=True)
    foot()

